const item = $input.first().json.body || $input.first().json;
const prompt = "You are an autonomous AI specialist for Mana Community Platform operations: Commercial store fitout compliance inspector. Audits architectural drawings, structural partition loads, fire sprinkler clearances, electrical load sanctions, and signage bylaws prior to permit issuance.

Analyze the following input payload securely:
__DATA__

Respond strictly with valid JSON conforming to this schema:
{"unitNumber":"Unit B-101 (First Floor Commercial)","applicantName":"Aroma Coffee Roasters","fitoutStatus":"APPROVED_WITH_CONDITIONS","sanctionedPowerKw":25,"requestedPowerKw":28,"inspectionFindings":{"structuralPartitions":"Lightweight gypsum partitions compliant with slab weight limit.","fireSprinklers":"Sprinkler head coverage maintained at 3.5m spacing with no ceiling obstruction.","exhaustDucting":"Requires commercial kitchen electrostatic precipitator before rooftop vent.","facadeSignage":"Signage dimensions within 12ft x 3ft society facade uniform guidelines."},"safetyConditions":["Install Class-K wet chemical fire extinguisher in kitchen area.","Complete electrical load test before final energization."],"fitoutPermitNumber":"FITOUT-2026-COMM-14"}

Rules:
- Return pure JSON only, no markdown wrapping, no extra keys.
- Never expose PII or confidential tenant data.
- Ensure realistic domain heuristics.";
return [{ json: { prompt: prompt.replace("__DATA__", JSON.stringify(item, null, 2)), originalInput: item } }];

const inputData = $input.first().json;
try {
  const text = inputData.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error("No Gemini output text");
  const parsed = JSON.parse(text);
  return [{ json: { status: "success", auditedAt: new Date().toISOString(), ...parsed } }];
} catch (e) {
  return [{ json: { status: "fallback", error: e.message, auditedAt: new Date().toISOString(), ...{"unitNumber":"Unit B-101 (First Floor Commercial)","applicantName":"Aroma Coffee Roasters","fitoutStatus":"APPROVED_WITH_CONDITIONS","sanctionedPowerKw":25,"requestedPowerKw":28,"inspectionFindings":{"structuralPartitions":"Lightweight gypsum partitions compliant with slab weight limit.","fireSprinklers":"Sprinkler head coverage maintained at 3.5m spacing with no ceiling obstruction.","exhaustDucting":"Requires commercial kitchen electrostatic precipitator before rooftop vent.","facadeSignage":"Signage dimensions within 12ft x 3ft society facade uniform guidelines."},"safetyConditions":["Install Class-K wet chemical fire extinguisher in kitchen area.","Complete electrical load test before final energization."],"fitoutPermitNumber":"FITOUT-2026-COMM-14"} } }];
}
